#include <stdio.h>
#define POTENCIA 10
int main(){
    int n, dig;
    int i = POTENCIA, contador = 0, soma = 0;
    scanf("%d", &n);
    while (n > 0){
        dig = n % i;
        ++contador;
        n /= i;
        i = i * POTENCIA;
        soma += dig;
    }
    printf("%d\n%d\n",contador, soma);
    return 0;
}

#include <stdio.h>

int main() {

    int value, num = 0, soma = 0, var, dig;

    scanf("%d", &value);
    var = value;

    if (value < 10)
        printf("1\n%d\n", value);
    else
        while (var >= 10) {
            dig = var % 10;
            soma += dig;
            num++;
            var = var / 10;

        printf("%d\n%d\n", num + 1, soma + var);
    }

    return 0;
}

#include <stdio.h>

int main(){
    int n, count, d = 10, sum = 0;
    scanf("%d", &n);

    while (n != 0){
        sum += (n % d);
        printf("%d\n", sum);
        n /= d;
        count++;
    }

    printf("%d\n%d\n", count, sum);
    return 0;
}

#include <stdio.h>

int main() {
    int N, NumDigit = 0, Soma = 0, Digit;

    printf("Introduza um numero inteiro:\n");
    scanf("%d", &N);

    while (N > 0) {
        Digit = N % 10;
        Soma += Digit;
        NumDigit++;
        N /= 10;
    }
    printf("O numero de digitos e: %d\n", NumDigit);
    printf("A soma dos digitos e: %d\n", Soma);
    return 0;
}

